mapper.select:
SELECT id, execution_id, user_id, conversation_id, tool, args_hash, status, result,
       error_code, error_message, created_at, updated_at
FROM ai_tool_execution
WHERE user_id = #{userId}
  AND execution_id = #{executionId}

mapper.update:
UPDATE ai_tool_execution
SET status = 'SUCCEEDED', result = #{result}, error_code = NULL, error_message = NULL, updated_at = now()
WHERE user_id = #{userId}
  AND execution_id = #{executionId}
  AND status = 'RUNNING'

UPDATE ai_tool_execution
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage}, updated_at = now()
WHERE user_id = #{userId}
  AND execution_id = #{executionId}
  AND status = 'RUNNING'

UPDATE ai_tool_execution
SET status = 'RUNNING', error_code = NULL, error_message = NULL, updated_at = now()
WHERE user_id = #{userId}
  AND execution_id = #{executionId}
  AND (
      status = 'FAILED'
      OR (status = 'RUNNING' AND updated_at < now() - make_interval(secs => #{staleSeconds}))
  )
